export interface FactoryRunUsage {
  factoryRunUsageId: number;
  factoryRunRef: string;
  promptTokens: number;
  completionTokens: number;
  totalTokens: number;
  costUSD: number;
  modelName: string;
  timestamp: string;
  created_At: string;
  updated_at?: string;
}

export interface FactoryRunUsageListResponse {
  factoryRunUsages: FactoryRunUsage[];
}

// GET ALL — POST /all_factoryRunUsages
export async function getAllFactoryRunUsages(): Promise<FactoryRunUsage[]> {
  const res = await fetch(BASE_URL + "/all_factoryRunUsages", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{}] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: FactoryRunUsageListResponse = await res.json();
  return data.factoryRunUsages ?? [];
}

// GET ONE — POST /one_factoryRunUsages
export async function getFactoryRunUsageById(id: number): Promise<FactoryRunUsage | undefined> {
  const res = await fetch(BASE_URL + "/one_factoryRunUsages", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "factoryRunUsageId": id }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: FactoryRunUsageListResponse = await res.json();
  return data.factoryRunUsages?.[0];
}

// CREATE — action: "INSERT"
export async function createFactoryRunUsage(payload: Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at">): Promise<FactoryRunUsage> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": "INSERT", ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: "UPDATE"
export async function updateFactoryRunUsage(id: number, payload: Partial<Omit<FactoryRunUsage, "factoryRunUsageId" | "created_At" | "updated_at">>): Promise<FactoryRunUsage> {
  const res = await fetch(BASE_URL + "/factoryRunUsages", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "factoryRunUsages": [{ "action": "UPDATE", "factoryRunUsageId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

